from pathlib import Path
import json,hashlib,datetime

root=Path('E:/Samplinglib'); out=Path(__file__).resolve().parent
def raw(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def pin(p):return dict(path=str(p.resolve()),raw_sha256=raw(p),bytes=p.stat().st_size)
def write(name,x):
 p=out/name;assert not p.exists(),str(p)
 p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n');return p
def append(event,**kw):
 with (out/'chronology.source-first89.native.jsonl').open('a',encoding='utf-8',newline='\n') as f:
  f.write(json.dumps(dict(event=event,utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),**kw),ensure_ascii=False)+'\n')
